/**
 * @license
 * AeroBot Stylized Aerial Sentry Drone 3D Model
 * Procedural Three.js asset matching 1:1 reference concept art with PBR shaders,
 * coaxial dual-rotor propulsion, articulated claw armor shields, look-dev lighting,
 * and 10 baked hierarchical animation clips (glTF-sourced from AeroBot_Sentry_Drone.glb).
 * Compatible with low_poly_3d and standalone Three.js compilation toolchains.
 */

import * as THREE from 'three';

export type ColorThemeId = 'hazard-orange' | 'stealth-phantom' | 'arctic-rescue' | 'cyber-neon' | 'military-camo';
export type AnimationName = 'hover' | 'fly' | 'boost' | 'scan' | 'land' | 'alert' | 'celebrate' | 'win' | 'victory' | 'death' | 'idle';

export interface ColorScheme {
  id: ColorThemeId;
  name: string;
  primaryOrange: string;
  primaryDark: string;
  whiteArmor: string;
  innerCream: string;
  secondaryGunmetal: string;
  metallicDark: string;
  accentBolt: string;
  opticGlow: string;
  opticGlowSecondary: string;
  description: string;
}

export interface ClawRig {
  index: number;
  name: string;
  side: 'left' | 'right';
  shoulderPivot: THREE.Group;
  elbowPivot: THREE.Group;
  wristPivot: THREE.Group;
  upperArmMesh: THREE.Mesh;
  forearmShield: THREE.Group;
  clawTip: THREE.Group;
  baseAngle: number;
}

export interface AeroDroneOptions {
  colorScheme?: ColorThemeId;
  wearLevel?: number;
  castShadow?: boolean;
  receiveShadow?: boolean;
}

export interface DetailInventoryItem {
  id: string;
  region: string;
  kind: 'feature' | 'panel' | 'decal' | 'landmark' | string;
  priority: 'high' | 'medium' | 'low' | string;
  reviewThreshold: number;
  name?: string;
  feature?: string;
  category?: string;
  pass?: string;
  description?: string;
  location?: string;
  meshName?: string;
  nodes?: string[];
}

export interface AeroDroneRuntime {
  root: THREE.Group;
  nodes: {
    baseChassis: THREE.Group;
    bodyOrb: THREE.Group;
    shellOrange: THREE.Mesh;
    whiteStripes: THREE.Group;
    turbineCowling: THREE.Mesh;
    turbineCore: THREE.Mesh;
    eyeGlowLight: THREE.PointLight;
    topMast: THREE.Group;
    topRotorHub: THREE.Group;
    bottomRotorHub: THREE.Group;
    topBlades: THREE.Mesh[];
    bottomBlades: THREE.Mesh[];
    antennaRoot: THREE.Group;
    antennaWhip: THREE.Group;
    antennaBall: THREE.Mesh;
    ventLeft: THREE.Group;
    ventRight: THREE.Group;
    collarGlowRing: THREE.Mesh;
    claws: ClawRig[];
    cables: THREE.Mesh[];
    sockets: {
      eye: THREE.Object3D;
      topRotor: THREE.Object3D;
      underThruster: THREE.Object3D;
      clawTips: THREE.Object3D[];
    };
    colliders: THREE.Box3[];
  };
  materials: {
    primaryPaint: THREE.MeshStandardMaterial;
    whitePanels: THREE.MeshStandardMaterial;
    innerCream: THREE.MeshStandardMaterial;
    gunmetal: THREE.MeshStandardMaterial;
    darkSteel: THREE.MeshStandardMaterial;
    polishedSteel: THREE.MeshStandardMaterial;
    opticGlow: THREE.MeshStandardMaterial;
    neonCyanRing: THREE.MeshStandardMaterial;
  };
  animations: {
    clips: THREE.AnimationClip[];
    mixer: THREE.AnimationMixer;
    actions: Map<string, THREE.AnimationAction>;
  };
  state: {
    currentAnimation: AnimationName;
    rotorSpeed: number;
    flightElevation: number;
    tiltAngle: THREE.Vector3;
    isScanning: boolean;
    aimTarget: THREE.Vector3 | null;
    wearLevel: number;
    colorScheme: ColorThemeId;
    hoverTime: number;
  };
  passes: {
    blockout: { name: string; completed: boolean; score: number };
    structural: { name: string; completed: boolean; score: number };
    form: { name: string; completed: boolean; score: number };
    material: { name: string; completed: boolean; score: number };
    surface: { name: string; completed: boolean; score: number };
    lighting: { name: string; completed: boolean; score: number };
    interaction: { name: string; completed: boolean; score: number };
    optimization: { name: string; completed: boolean; score: number };
  };
  passesComplete: boolean;
  passesReviewed: Record<string, { score: number; notes?: string }>;
  detailInventory: DetailInventoryItem[];
  playAnimation(name: AnimationName, crossFadeDuration?: number): void;
  stopAnimations(): void;
  setScanning(scanning: boolean): void;
  setJointAngles(angles: any): void;
  aimAt(worldTarget: THREE.Vector3, damping?: number): void;
  setColorScheme(themeId: ColorThemeId): void;
  setWearLevel(level: number): void;
  setWireframe(wireframe: boolean): void;
  getEyeWorldPosition(targetVec?: THREE.Vector3): THREE.Vector3;
  update(deltaTime: number): void;
  tick(deltaTime?: number): void;
  dispose(): void;
}

