/**
 * Baked animation curve data extracted 1:1 from the reference AeroBot_Sentry_Drone.glb export.
 * Each entry is a raw glTF-style sampler: target node name, TRS path, keyframe times (seconds),
 * and flattened output values (3 floats/key for translation & scale, 4 floats/key XYZW for rotation).
 * This is the ground-truth rig data baked in the source DCC file — do not hand-edit these numbers,
 * regenerate them from the .glb if the source animation changes.
 */
interface BakedTrackData {
  node: string;
  path: 'translation' | 'rotation' | 'scale';
  times: number[];
  values: number[];
}

