/**
 * Clip names whose baked .glb data already animates the rotor hubs.
 * Only 'alert' has no rotor keyframes of its own (the source .glb never
 * touches Node_TopRotorHub/Node_BottomRotorHub during that clip) — every
 * other clip drives the rotors directly via the AnimationMixer. Used to
 * gate the procedural "rotor blur" fallback below so it never fights the
 * baked motion (see update()).
 */
const ROTOR_DRIVEN_CLIPS = new Set<string>(
  Object.entries(AERO_DRONE_BAKED_ANIMATIONS)
    .filter(([, clip]) => clip.tracks.some((t) => t.node === 'Node_TopRotorHub' || t.node === 'Node_BottomRotorHub'))
    .map(([name]) => name)
);
ROTOR_DRIVEN_CLIPS.add('idle'); // 'idle' aliases the 'hover' clip, which is rotor-driven

/**
 * Builds a THREE.AnimationClip from baked glTF-style track data, using
 * QuaternionKeyframeTrack for rotation channels (matches the source .glb sampler
 * output exactly) and VectorKeyframeTrack for translation/scale channels.
 */
// Maps glTF TRS path names to the three.js Object3D property names that
// THREE.PropertyBinding actually resolves. This is the critical translation
// step: glTF calls it 'translation' / 'rotation' / 'scale', but three.js
// exposes those as '.position' / '.quaternion' / '.scale' on Object3D —
// using the glTF names verbatim silently fails to bind (no error, no motion).
const GLTF_PATH_TO_THREE_PROPERTY: Record<BakedTrackData['path'], string> = {
  translation: 'position',
  rotation: 'quaternion',
  scale: 'scale',
};

function buildBakedAnimationClip(clipName: string, duration: number, tracks: BakedTrackData[]): THREE.AnimationClip {
  const keyframeTracks: THREE.KeyframeTrack[] = tracks.map((t) => {
    const trackName = `${t.node}.${GLTF_PATH_TO_THREE_PROPERTY[t.path]}`;
    if (t.path === 'rotation') {
      // Baked as quaternions in the source .glb — must target '.quaternion',
      // not '.rotation' (an Euler triple, a different buffer type/size).
      return new THREE.QuaternionKeyframeTrack(trackName, t.times, t.values);
    }
    return new THREE.VectorKeyframeTrack(trackName, t.times, t.values);
  });
  return new THREE.AnimationClip(clipName, duration, keyframeTracks);
}

/**
 * Procedural wear and subtle surface grain
 */
function createProceduralDroneCanvas(width = 512, height = 512): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) return canvas;

  ctx.fillStyle = '#9e9e9e';
  ctx.fillRect(0, 0, width, height);

  const imgData = ctx.getImageData(0, 0, width, height);
  const data = imgData.data;

  for (let i = 0; i < data.length; i += 4) {
    const grain = (Math.random() - 0.5) * 18;
    const val = Math.min(255, Math.max(0, data[i] + grain));
    data[i] = val;
    data[i + 1] = val;
    data[i + 2] = val;
  }
  ctx.putImageData(imgData, 0, 0);

  return canvas;
}

/**
 * Procedural eye lens gradient texture
 */
function createEyeGlowCanvas(width = 256, height = 256): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) return canvas;

  const grad = ctx.createRadialGradient(width * 0.5, height * 0.5, 4, width * 0.5, height * 0.5, width * 0.48);
  grad.addColorStop(0, '#ffffff');
  grad.addColorStop(0.2, '#99f6ff');
  grad.addColorStop(0.55, '#00c8e8');
  grad.addColorStop(0.85, '#0077b6');
  grad.addColorStop(1.0, '#003a6b');

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // Soft iris targeting ring
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.45)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.arc(width * 0.5, height * 0.5, width * 0.28, 0, Math.PI * 2);
  ctx.stroke();

  return canvas;
}

/**
 * Curved aerodynamic propeller blade geometry with rounded wingtip
 */
function createCurvedRotorBladeGeometry(): THREE.BufferGeometry {
  const shape = new THREE.Shape();
  shape.moveTo(0, -0.07);
  shape.lineTo(0.22, -0.11);
  shape.quadraticCurveTo(0.95, -0.17, 1.52, -0.09);
  shape.quadraticCurveTo(1.75, 0.0, 1.68, 0.11);
  shape.quadraticCurveTo(1.38, 0.2, 0.72, 0.16);
  shape.quadraticCurveTo(0.25, 0.11, 0, 0.07);
  shape.closePath();

  const extrudeSettings: THREE.ExtrudeGeometryOptions = {
    depth: 0.042,
    bevelEnabled: true,
    bevelSegments: 4,
    steps: 1,
    bevelSize: 0.018,
    bevelThickness: 0.018,
  };

  const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geom.center();
  return geom;
}

